interface_sketch_ts:
TypeScript minimal interfaces (for discussion):

export type Envelope = {
  session_id: string;
  seq: number;
  type: 'start' | 'partial' | 'tool_request' | 'tool_response' | 'complete' | 'error' | 'keepalive';
  payload?: unknown; // structured output or tool metadata
  retryable?: boolean;
};

export interface ProgressiveInvocation {
  onEvent(cb: (env: Envelope) => void): void;
  stream(): AsyncIterable<Envelope>; // high-level iterator
  cancel(): Promise<void>;
  resume(sessionId: string): ProgressiveInvocation;
}

Example usage (consumer):
for await (const ev of client.invokeProgressive({prompt})) {
  if (ev.type === 'partial') { render(ev.payload as string); }
  if (ev.type === 'tool_request') { await myToolRunner.handle(ev.payload); }
}

interface_sketch_go:
Go minimal interfaces (for discussion):

type Envelope struct {
  SessionID string `json:\"session_id\"`
  Seq int `json:\"seq\"`
  Type string `json:\"type\"`
  Payload json.RawMessage `json:\"payload,omitempty\"`
  Retryable bool `json:\"retryable,omitempty\"`
}

type ProgressiveInvocation interface {
  Events(ctx context.Context) (<-chan Envelope, <-chan error)
  Cancel(ctx context.Context) error
  Resume(ctx context.Context, sessionID string) (ProgressiveInvocation, error)
}

// consumer loop
for ev := range events {
  switch ev.Type {
  case \"partial\": fmt.Print(string(ev.Payload))
  case \"tool_request\": go handleTool(ev.Payload) // non-blocking
  }
}
